--Terris_Thule (223075)
--Phase 4 Encounter
--potimeb

local event_mobs = {223079,223081,223080,223082};

function event_death_complete(e)
	eq.signal(223097,223075); -- Add Loot Lockout
	eq.signal(223097,5); -- send a signal to the zone_status that I died
end

function event_spawn(e)
	eq.set_next_hp_event(91);
end

function event_hp(e)
	if (e.hp_event == 91) then
		SpawnAdds();
		eq.set_next_hp_event(51);
	elseif (e.hp_event == 51) then
		SpawnAdds();
		eq.set_next_hp_event(11);
	elseif (e.hp_event == 11) then
		SpawnAdds();
	end
end

function event_combat(e)
	if e.joined then
		eq.stop_timer("reset");
	else
		eq.set_timer("reset",5 * 60 * 1000);
	end
end

function event_timer(e)
	if e.timer == "reset" then
		eq.stop_timer("reset");
		eq.set_next_hp_event(91);
		for k,v in pairs(event_mobs) do	--depop adds
			eq.depop_all(v);
		end
	end
end

function SpawnAdds()	--spawns 4 adds (2 sets of same type)  -- A_Summoned_Knight_of_Terris,A_Phantasm_of_Terris,A_Nightmare_Knight_of_Terris
	local id1 = event_mobs[math.random(#event_mobs)];	
	local id2 = nil;

	while id2 == nil do
		id2 = event_mobs[math.random(#event_mobs)];	--select 2nd add, but must be different than first selection
		if id2 == id1 then
			id2 = nil;		--reset to roll again if same mob id
		end
	end

	for n = 1,2 do
		mob = eq.spawn2(id1,0,0,-219,344,348,256);
		mob:CastToNPC():MoveTo(-219,250,348,256,true);
		mob2 = eq.spawn2(id2,0,0,-347,210,348,128);
		mob2:CastToNPC():MoveTo(-260,210,348,128,true);
	end
end

-- items: 18821
function event_say(e)
  if(e.message:findi("hail")) then
    e.self:Say(string.format("Hail, %s! Are you new to Qeynos? If you are, I highly recommend stopping by the Lion's Mane Tavern for the best ale in Antonica. Oh, did I mention that my brother Earron is the master brewer there? Tell him [Kwint sent] you.",e.other:GetName()));
  end
end

function event_trade(e)
  local item_lib =require("items");
  if(item_lib.check_turn_in(e.trade, {item1 = 18821})) then
    e.self:QuestSay(e.other, "Hey. Thanks! Sorry about that 'he's my brother' bit but I am sure you had a good time at the Lion's Mane anyway. I sure didn't lie to you about the quality of the ale there.");
    e.other:Faction(262,10,0); -- Faction: Guards of Qeynos
    e.other:Faction(219,10,0); -- Faction: Antonius Bayle
    e.other:Faction(223,-20,0); -- Faction: Circle of Unseen Hands
    e.other:Faction(230,-20,0); -- Faction: Corrupt Qeynos Guards
    e.other:Faction(291,10,0); -- Faction: Merchants of Qeynos
    e.other:AddEXP(8000);
	e.other:GiveCash(8,0,0,0);
  end
  item_lib.return_items(e.self, e.other, e.trade)
end

function event_combat(e)
  if e.joined then
    e.self:Say(string.format("Time to die %s!",e.other:GetCleanName()));
  end
end

function event_scale_calc(e)
	local zone_id = eq.get_zone_id();

	if zone_id > 228 and zone_id < 277 then
		e.self:SetScale(1);
	else
		e.self:SetScale(0);
	end
end

-- a_time_traveler
--potimea

function event_say(e)
	if(e.message:findi("hail") and not e.self:IsEngaged()) then
		if e.self:GetX() == -412 and e.self:GetY() == 1111 then
			e.self:Say("Hello, " .. e.other:GetName() .. ".  I find myself here as a result of my physical condition.  I was once a great sorceror of Erudin.  My work founded entire schools of magic and I have trained innumerable sages in the ways of the arcane.  As time passed and my life grew short I became desperate and manufactured a magical transporter that would entrap me in time until a cure for my condition could be found.  As a side effect of the transportation my short-term memory was damaged.  I... have no idea how long I've been trapped here.");
		elseif e.self:GetX() == -493 and e.self:GetY() == 1142 then
			e.self:Say("I was once a cleric in the undead army of Bertoxxulous, yet now I have been doomed to walk these lands.  I was facing an adversary that wielded a magical greatsword that glowed with an unholy aura.  The moment this blade struck my body I fell to the ground only to awaken here.");
		elseif e.self:GetX() == -559 and e.self:GetY() == 1074 then	
			e.self:Say("Greetings!  What business do you have here, " .. e.other:GetName() .. "?  I have been here for a very long time after being exposed to a glowing stone back in my home of Erudin City.  There were a number of gypsies that approached us with it in their possession.  I still do not understand how it did not transport them here as it did to us.");
		elseif e.self:GetX() == -648 and e.self:GetY() == 1113 then	
			e.self:Say("Hello, stranger. What are your reasons for venturing into this realm? I must say that I am here only for the sake of research. While I was attempting to construct a teleport device it began to shake and tremble with unbelievable force.  I touched it and then found myself here.");
		elseif e.self:GetX() == -651 and e.self:GetY() == 1201 then	
			e.self:Say("It is very nice to meet you, " .. e.other:GetName() .. ". I hope you don't mind that I am unable to talk.  I have just recently arrived here and I have many tests to do.");
		end
	end
end

